details.uri:
={{ ((item) => {
    let isTruncated = item.json.contentSnippet.length > 300;

    return !isTruncated && item.json.link.includes('/scrap/') ? '' : item.json.link.replace('utm_medium=feed', 'utm_medium=bsky');
})($('RSS Feed Trigger').item) }}
